sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.ch-login {
  width: 100%;
  box-sizing: border-box;
  padding: 70px 0 90px;
  background: #faf6ef;
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Arial, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  color: #2a2d29;
}
.ch-login *, .ch-login *::before, .ch-login *::after { box-sizing: border-box; }

.ch-login-container { width: 92%; max-width: 460px; margin: 0 auto; }

.ch-login-card {
  padding: 36px 34px 34px;
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 8px;
  box-shadow: 0 10px 30px rgba(31, 58, 48, .08);
}

.ch-login-logo { display: block; height: 52px; width: auto; margin: 0 auto 22px; }

.ch-login-card h1 {
  margin: 0;
  text-align: center;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 2.1rem;
  font-weight: 600;
  line-height: 1.15;
  color: #1f3a30;
}
.ch-login-sub { margin: 6px 0 20px; text-align: center; color: #6f756f; font-size: .9rem; }

.ch-login-note {
  margin-bottom: 22px;
  padding: 12px 14px;
  background: #e8eee9;
  border-left: 3px solid #d4b07c;
  border-radius: 4px;
  color: #444a44;
  font-size: .85rem;
  line-height: 1.55;
}
.ch-login-note a { color: #1f3a30; font-weight: 600; text-decoration: underline; }

.ch-login-field { margin-bottom: 16px; }
.ch-login-field label {
  display: block;
  margin: 0 0 6px;
  font-size: .72rem;
  font-weight: 500;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: #6f756f;
}
.ch-login-field input {
  display: block;
  width: 100%;
  height: auto;
  margin: 0;
  padding: 11px 14px;
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 6px;
  box-shadow: none;
  font-family: inherit;
  font-size: .95rem;
  color: #2a2d29;
  outline: none;
  transition: .2s;
}
.ch-login-field input:focus { border-color: #1f3a30; box-shadow: 0 0 0 3px rgba(31, 58, 48, .1); }

.ch-login-btn {
  display: block;
  width: 100%;
  margin-top: 6px;
  padding: 12px 26px;
  background: #1f3a30;
  color: #ffffff;
  border: 1px solid transparent;
  border-radius: 6px;
  font-family: inherit;
  font-size: .78rem;
  font-weight: 600;
  letter-spacing: .12em;
  text-align: center;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: .25s ease;
}
.ch-login-btn:hover { background: #162a22; color: #ffffff; transform: translateY(-2px); box-shadow: 0 10px 30px rgba(31, 58, 48, .08); }

.ch-login-done { text-align: center; }
.ch-login-done .ch-login-link { margin-top: 8px; }
.ch-login-back { display: inline-block; margin-top: 16px; color: #1f3a30; font-size: .85rem; font-weight: 600; text-decoration: none; }
.ch-login-back:hover { color: #a8895e; }

sp_widget.script:
(function() {
    data.isLoggedIn = gs.isLoggedIn();
    data.userName = data.isLoggedIn ? gs.getUserDisplayName() : '';

    // Where to send the user after logging in
    var redirect = $sp.getParameter('redirect_to') || '';

    // If they were bounced here from a protected page (like My Reservations),
    // send them back to that page after login
    var pageId = $sp.getParameter('id') || '';
    if (!redirect && /^[a-z0-9_]+$/.test(pageId) && pageId !== 'login' && pageId !== 'hotel_login') {
        redirect = '/hotel?id=' + pageId;
    }

    // Only allow local paths (blocks redirects to other websites)
    if (!redirect || redirect.charAt(0) !== '/' || redirect.charAt(1) === '/') {
        redirect = '/hotel?id=hotel_reservation_home_page';
    }
    data.redirectTo = redirect;
})();
